    axis = max(range(h), key=lambda r: sum(v == 6 for v in grid[r]))
    out = [row[:] for row in grid]

    bars = []
    c = 0
    while c < w:
        color = grid[axis][c]
        if color in (6, 8):
            c += 1
            continue

        cols = [c]
        j = c + 1
        while j < w and grid[axis][j] == color:
            cols.append(j)
            j += 1

        heights = []
        for col in cols:
            r = axis - 1
            while r >= 0 and grid[r][col] == color:
                r -= 1
            up = axis - 1 - r

            r = axis + 1
            while r < h and grid[r][col] == color:
                r += 1
            down = r - axis - 1
            heights.append(up + 1 + down)

        bars.append((color, cols, min(heights)))
        c = j

    sorted_heights = sorted(bar[2] for bar in bars)

    # Remove each bar's original vertical extent.
    for color, cols, _ in bars:
        for col in cols:
            r = axis
            while r >= 0 and grid[r][col] == color:
                out[r][col] = 8
                r -= 1
            r = axis + 1
            while r < h and grid[r][col] == color:
                out[r][col] = 8
                r += 1

    # Reassign the heights in increasing order from left to right.
    for (color, cols, _), height in zip(bars, sorted_heights):
        top = axis - height // 2
        for r in range(top, top + height):
            if 0 <= r < h:
                for col in cols:
                    out[r][col] = color

    return out
